using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEngine;
namespace ArenaTatica.Core.Tests {
public class InventoresLunaTests {
 static object Call(Match m,string method,params object[] args) => typeof(Match).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(m,args);
 static Match New(string a,string b="ciantia") { var m=Match.New(new MatchSetup{flatMap=true,seed=71,mode=VictoryMode.Eliminacao,players=new[]{new PlayerSetup{fighters=new[]{a}},new PlayerSetup{fighters=new[]{b}}}}); foreach(var t in m.S.tiles){t.terrain=Terrain.Livre;t.coins=0;t.height=0;t.obj=0;t.zone=false;t.lava=false;} m.S.Luna.gears.Clear(); int k=0;foreach(var f in m.S.fighters){f.cell=new Cell(1+k++,1);f.pa=12;f.pm=5;} var hero=m.S.fighters.First(x=>x.team==1&&x.summoner==0);hero.cell=new Cell(4,4);m.S.active=m.S.timeline.IndexOf(hero.id);return m; }
 static Fighter Hero(Match m,int team=1)=>m.S.fighters.First(f=>f.team==team&&f.summoner==0);
 static bool Skill(Match m,Fighter f,string id,Cell c,out string why,Cell? c2=null){m.S.active=m.S.timeline.IndexOf(f.id);return m.Apply(new Command{kind="skill",fighter=f.id,skill=id,cell=c,cell2=c2??Cell.Unknown,revision=m.S.revision},f.team,out _,out why);}
 [TestCase("nikola")][TestCase("bifia")][TestCase("desland")][TestCase("nepturius")] public void HeroDefaultsAreEditableAndPickable(string id){var d=Content.Fighters[id];Assert.IsTrue(d.picker);Assert.AreEqual(11,d.hp);Assert.AreEqual(6,d.pa);Assert.AreEqual(3,d.pm);Assert.NotNull(d.luna);Assert.IsTrue(d.skills.All(s=>s.pa>=0));}
 [Test] public void NikolaStartsWithExactlyTwoAutomaticRobots(){var m=New("nikola");var n=Hero(m);var robots=m.S.fighters.Where(f=>f.summoner==n.id).ToArray();Assert.AreEqual(2,robots.Length);CollectionAssert.AreEquivalent(new[]{"blip","celinos"},robots.Select(x=>x.def));Assert.IsTrue(robots.All(x=>x.hp==3&&!m.S.timeline.Contains(x.id)));Assert.AreEqual(3,m.S.fighters.Where(x=>x.team==1).Select(x=>x.cell).Distinct().Count());}
 [Test] public void NikolaDropsFiveGearsEveryFourRoundsInDuel(){var m=New("nikola");Assert.AreEqual(4,m.GearEvery());m.S.round=3;Call(m,"LunaBeginTurn",Hero(m));Assert.AreEqual(0,m.S.Luna.gears.Count,"x1: só a cada 4");m.S.round=5;Call(m,"LunaBeginTurn",Hero(m));Assert.AreEqual(5,m.S.Luna.gears.Count);}
 [Test] public void NikolaDropsGearsWithTwoHitMarkers(){var m=New("nikola");Call(m,"LunaBeginTurn",Hero(m));Assert.AreEqual(5,m.S.Luna.gears.Count);Assert.IsTrue(m.S.Luna.gears.All(x=>x.hits==2&&(x.value==1||x.value==2)));}
 [Test] public void OwnGearCollectionIncreasesSharedCounter(){var m=New("nikola");var n=Hero(m);m.S.Luna.gears.Add(new Gear{owner=n.id,cell=Board.Index(m.S,n.cell),value=2,hits=3});Call(m,"Collect",n);Assert.AreEqual(2,m.FamilyGears(n.id));Assert.IsEmpty(m.S.Luna.gears);}
 [Test] public void OtherAllyGetsOnlyCurrentTurnPaAndPm(){var m=New("nikola");var n=Hero(m);var ally=Hero(m,2);m.S.alliance[2]=m.S.alliance[1];int pa=ally.pa,pm=ally.pm;m.S.Luna.gears.Add(new Gear{owner=n.id,cell=Board.Index(m.S,ally.cell),value=2,hits=3});Call(m,"Collect",ally);Assert.AreEqual(pa+2,ally.pa);Assert.AreEqual(pm+4,ally.pm);Assert.AreEqual(0,m.FamilyGears(n.id));Assert.IsEmpty(ally.buffs);}
 [Test] public void EnemyCannotCollectGears(){var m=New("nikola");var n=Hero(m);var e=Hero(m,2);m.S.Luna.gears.Add(new Gear{owner=n.id,cell=Board.Index(m.S,e.cell),value=1,hits=3});Call(m,"Collect",e);Assert.AreEqual(1,m.S.Luna.gears.Count);}
 [Test] public void GearNeedsThreeSeparateHitsRegardlessOfDamage(){var m=New("nikola");var n=Hero(m);var e=Hero(m,2);var c=new Cell(7,7);m.S.Luna.gears.Add(new Gear{owner=n.id,cell=Board.Index(m.S,c),value=1,hits=3});var log=new List<GameEvent>();Call(m,"GearHits",e,new[]{c},log);Assert.AreEqual(2,m.S.Luna.gears[0].hits);Call(m,"GearHits",e,new[]{c},log);Assert.AreEqual(1,m.S.Luna.gears[0].hits);Call(m,"GearHits",e,new[]{c},log);Assert.IsEmpty(m.S.Luna.gears);}
 [Test] public void ValidationDoesNotCreateCounterOrConsumeRng(){var m=New("nikola");var n=Hero(m);string before=JsonUtility.ToJson(m.S);Assert.IsFalse(Skill(m,n,"eletaser",new Cell(16,16),out _));Assert.AreEqual(before,JsonUtility.ToJson(m.S));}
 [Test] public void DeadRobotRequiresItsPaidRespawnCommand(){var m=New("nikola");var n=Hero(m);var b=m.S.fighters.First(x=>x.def=="blip");b.hp=0;b.deathProcessed=true;Call(m,"LunaBeginTurn",n);Assert.IsFalse(m.S.fighters.Any(x=>x.Alive&&x.def=="blip"));int pa=n.pa;Assert.IsTrue(Skill(m,n,"comando-blip",n.cell,out var why),why);Assert.AreEqual(pa-3,n.pa);Assert.AreEqual(1,m.S.fighters.Count(x=>x.Alive&&x.def=="blip"));}
 [Test] public void RespawningBlipDoesNotRespawnCelinosForFree(){var m=New("nikola");var n=Hero(m);foreach(var r in m.S.fighters.Where(x=>x.summoner==n.id)){r.hp=0;r.deathProcessed=true;}Assert.IsTrue(Skill(m,n,"comando-blip",n.cell,out var why),why);Assert.AreEqual(1,m.S.fighters.Count(x=>x.Alive&&x.summoner==n.id));}
 [Test] public void LivingBlipOpensRemoteShopForThreePa(){var m=New("nikola");var n=Hero(m);int pa=n.pa;Assert.IsTrue(Skill(m,n,"comando-blip",n.cell,out var why),why);Assert.AreEqual(pa-3,n.pa);Assert.IsTrue(n.remoteShop);}
 [Test] public void RobotsSurviveOwnerKo(){var m=New("nikola");var n=Hero(m);n.hp=0;Call(m,"KO",n,null);Assert.AreEqual(2,m.S.fighters.Count(x=>x.Alive&&x.summoner==n.id));}
 [Test] public void MatrixTakesDamageWithoutBodyOverflow(){var m=New("nikola");var n=Hero(m);Assert.IsTrue(Skill(m,n,"matriz-protecao",n.cell,out var why),why);int hp=n.hp;var log=new List<GameEvent>();Call(m,"Hurt",n,20,log,Hero(m,2),true);Assert.AreEqual(hp,n.hp);Assert.AreEqual(0,m.S.Luna.machines.First(x=>x.by==n.id).box.hp);}
 [Test] public void MatrixBlocksOrdinaryMovement(){var m=New("nikola");var n=Hero(m);Assert.IsTrue(Skill(m,n,"matriz-protecao",n.cell,out var why),why);var before=n.cell;Assert.IsFalse(m.Apply(new Command{kind="mover",fighter=n.id,cell=n.cell+new Cell(1,0),revision=m.S.revision},n.team,out _,out _));Assert.AreEqual(before,n.cell);}
 [Test] public void SonusUsesHalfBifiaPmAndZerosAllyPm(){var m=New("bifia");var b=Hero(m);var ally=Hero(m,2);m.S.alliance[2]=m.S.alliance[1];ally.cell=new Cell(5,4);ally.hp=3;ally.pm=7;b.pm=5;Assert.IsTrue(Skill(m,b,"tiro-sonus",ally.cell,out var why),why);Assert.AreEqual(5,ally.hp);Assert.AreEqual(0,ally.pm);Assert.AreEqual(5,b.pm);Assert.IsTrue(b.cooldowns.Any(x=>x.skill=="tiro-sonus"&&x.uses==2));}
 [Test] public void SonusCannotAffectTechnologicalAlly(){var m=New("bifia","nikola");var b=Hero(m);var n=Hero(m,2);m.S.alliance[2]=m.S.alliance[1];n.cell=new Cell(5,4);Assert.IsFalse(Skill(m,b,"tiro-sonus",n.cell,out _));}
 [Test] public void CastlingUsesFirstAllyAsKing(){var m=New("desland");var f=Hero(m);var a=Hero(m,2);m.S.alliance[2]=m.S.alliance[1];f.cell=new Cell(3,4);a.cell=new Cell(7,4);Assert.IsTrue(Skill(m,f,"roque",f.cell,out var why,a.cell),why);Assert.AreEqual(new Cell(5,4),f.cell);Assert.AreEqual(new Cell(4,4),a.cell);}
 [Test] public void InvalidCastlingIsAtomic(){var m=New("desland");var f=Hero(m);var a=Hero(m,2);m.S.alliance[2]=m.S.alliance[1];a.cell=f.cell+new Cell(2,2);string state=JsonUtility.ToJson(m.S);Assert.IsFalse(Skill(m,f,"roque",f.cell,out _,a.cell));Assert.AreEqual(state,JsonUtility.ToJson(m.S));}
 [Test] public void ChessDomainCreatesFiveDifferentPiecesWithoutKing(){var m=New("desland");var f=Hero(m);Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);var pieces=m.S.fighters.Where(x=>x.summoner==f.id&&x.def.StartsWith("peca-")).ToArray();Assert.AreEqual(5,pieces.Length);Assert.IsTrue(pieces.All(x=>x.hp==(x.def=="peca-torre"?3:1)));Assert.IsFalse(pieces.Any(x=>x.def.Contains("rei")));}
 [Test] public void NepturiusStartsWithSphere(){var m=New("nepturius");Assert.AreEqual(1,m.S.fighters.Count(x=>x.Alive&&x.def=="esfera-nepturius"&&x.summoner==Hero(m).id));}
 [Test] public void SphereNeverTakesDamage(){var m=New("nepturius");var sp=m.S.fighters.First(x=>x.def=="esfera-nepturius");int hp=sp.hp;Call(m,"Hurt",sp,999,new List<GameEvent>(),Hero(m,2),true);Assert.AreEqual(hp,sp.hp);}
 [Test] public void SphereAuraSparesOwnerAndNikola(){var m=New("nepturius","nikola");var n=Hero(m);var sp=m.S.fighters.First(x=>x.def=="esfera-nepturius");sp.cell=new Cell(5,4);n.pa=6;n.pm=3;Call(m,"SphereAura",n);Assert.AreEqual(6,n.pa,"dono imune à própria esfera");Assert.AreEqual(3,n.pm);var tech=Hero(m,2);tech.cell=new Cell(5,5);tech.pa=6;Call(m,"SphereAura",tech);Assert.AreEqual(6,tech.pa);}
 [Test] public void MadnessBlocksBlastUntilEndTurn(){var m=New("nepturius");var n=Hero(m);Assert.IsTrue(Skill(m,n,"loucura-negra",n.cell,out var why),why);Assert.IsFalse(Skill(m,n,"explosao-antimateria",n.cell,out _));}
 [Test] public void SphereMovesRelativeToItsOwnPosition(){var m=New("nepturius");var n=Hero(m);var sp=m.S.fighters.First(x=>x.def=="esfera-nepturius");sp.cell=new Cell(m.S.width-2,m.S.height-2);sp.pm=4;var to=sp.cell+new Cell(1,0);Assert.IsTrue(Skill(m,n,"mover-esfera",to,out var why),why);Assert.AreEqual(to,sp.cell);}
 [Test] public void RepeatedNepturiusHaveIndependentSpheres(){var m=New("nepturius","nepturius");Assert.AreEqual(2,m.S.fighters.Count(x=>x.def=="esfera-nepturius"));Assert.AreEqual(2,m.S.Luna.machines.Count);}
 [Test] public void WaterCostsTwoAndOnePmAllowsOneFirstStep(){var m=New("bifia");var f=Hero(m);f.pm=1;var to=f.cell+new Cell(1,0);m.S.At(f.cell).terrain=Terrain.Agua;m.S.At(to).terrain=Terrain.Agua;Assert.AreEqual(2,Board.StepCost(m.S,f.cell,to,false));Assert.NotNull(Board.Path(m.S,f,to,1));Assert.IsTrue(m.Apply(new Command{kind="mover",fighter=f.id,cell=to,revision=m.S.revision},f.team,out _,out var why),why);Assert.AreEqual(0,f.pm);}
 [Test] public void DocksAreOpenWaterMapWithDrySpawns(){var m=Match.New(new MatchSetup{theme=MapGen.DocksTheme,seed=1,team1=new[]{"ciantia"},team2=new[]{"bifia"}});Assert.IsFalse(MapGen.Closed(m.S.theme));Assert.IsTrue(m.S.tiles.Any(t=>t.terrain==Terrain.Agua));Assert.IsTrue(m.S.fighters.All(f=>m.S.At(f.cell).terrain!=Terrain.Agua));}
 [Test] public void NewStateSurvivesJsonRoundtrip(){var m=New("nikola");Call(m,"LunaBeginTurn",Hero(m));var s=JsonUtility.FromJson<MatchState>(JsonUtility.ToJson(m.S));Assert.AreEqual(m.S.Luna.gears.Count,s.Luna.gears.Count);Assert.AreEqual(m.S.Luna.machines.Count,s.Luna.machines.Count);}
 [Test] public void CelinosApproachesAnEnemyFromItsOwnPosition(){var m=New("nikola");var owner=Hero(m);var r=m.S.fighters.First(x=>x.def=="celinos");var enemy=Hero(m,2);r.cell=new Cell(1,4);enemy.cell=new Cell(m.S.width-2,4);int before=Board.Gap(r,enemy);Call(m,"ActCelinos",r,owner);Assert.Less(Board.Gap(r,enemy),before);}
 [Test] public void CelinosRevealsWithinFourCellsImmediately(){var m=New("nikola");var r=m.S.fighters.First(x=>x.def=="celinos");var enemy=Hero(m,2);r.cell=new Cell(1,4);enemy.cell=new Cell(5,4);enemy.hidden=true;Call(m,"RevealCelinos");Assert.IsTrue(Match.OnRadar(m.S,r.team,enemy));Assert.IsFalse(Match.Concealed(m.S,r.team,enemy));Assert.IsFalse(Match.ViewFor(m.S,r.team).F(enemy.id).hidden);}
 [Test] public void CelinosDoesNotRevealOutsideItsRadius(){var m=New("nikola");var r=m.S.fighters.First(x=>x.def=="celinos");var enemy=Hero(m,2);r.cell=new Cell(1,4);enemy.cell=new Cell(6,4);enemy.hidden=true;Call(m,"RevealCelinos");Assert.IsTrue(enemy.hidden);}
 [Test] public void BobettKillingMarkedCelinosKeepsTheGameGoing(){var m=New("nikola","rei-bobett");var n=Hero(m);var b=Hero(m,2);var r=m.S.fighters.First(x=>x.def=="celinos");b.cell=new Cell(5,5);r.cell=new Cell(6,5);r.hp=1;m.S.Luna.marks.Add(new LunaMark{by=n.id,id=b.id,x=5,z=5,round=m.S.round});Assert.IsTrue(Skill(m,b,"coroada",r.cell,out var why),why);Assert.IsFalse(r.Alive);for(int i=0;i<12&&!m.S.over;i++){var a=m.S.Active;Assert.IsNotNull(a);Assert.IsTrue(m.Apply(new Command{kind="passar",fighter=a.id,revision=m.S.revision},a.team,out _,out why),why);}Assert.IsTrue(ArenaGame.ValidState(m.S));}
 [Test] public void SixSharedGearsIncreaseRadarByTwo(){var m=New("nikola");var n=Hero(m);var r=m.S.fighters.First(x=>x.def=="celinos");var family=m.S.Luna.families.FirstOrDefault(x=>x.owner==n.id);if(family==null){family=new LunaFamily{owner=n.id};m.S.Luna.families.Add(family);}family.gears=6;Assert.AreEqual(6,Match.CelinosRadarRadius(m.S,r));}
 [Test] public void CelinosRadarAlsoWorksInFog(){var m=New("nikola");var r=m.S.fighters.First(x=>x.def=="celinos");r.cell=new Cell(1,4);m.S.fog=true;m.S.revealed=false;var seen=Fog.Vision(m.S,1);Assert.IsTrue(seen[Board.Index(m.S,new Cell(5,4))]);}
 [Test] public void SphereGrabCountsOnlyEligibleTargets(){var m=New("nepturius","nikola");var owner=Hero(m);owner.cell=new Cell(0,0);var sp=m.S.fighters.First(x=>x.def=="esfera-nepturius");sp.cell=new Cell(4,4);var cells=new[]{new Cell(4,5),new Cell(5,4),new Cell(4,3),new Cell(3,4)};var victims=new List<Fighter>();foreach(var c in cells){var f=new Fighter{id=m.S.fighters.Max(x=>x.id)+1,def="ciantia",team=2,hp=10,cell=c};m.S.fighters.Add(f);victims.Add(f);}Call(m,"SphereGrab",owner,false);Assert.IsTrue(victims.All(x=>x.stunned==1));}

 [Test] public void DescriptionsExplainRemoteShopAndDynamicSonus(){StringAssert.Contains("loja",Content.Describe(Content.Fighters["nikola"].skills.First(x=>x.id=="comando-blip")));StringAssert.Contains("metade dos PM",Content.Describe(Content.Fighters["bifia"].skills.First(x=>x.id=="tiro-sonus")));}
 [Test] public void PassiveDescriptionsExplainTechnologyAndSphere(){StringAssert.Contains("Proteção tecnológica",Content.Traits(Content.Fighters["nikola"]));StringAssert.Contains("esfera invulnerável",Content.Traits(Content.Fighters["nepturius"]));}

 [TestCase(1u,2)][TestCase(37u,2)][TestCase(71u,4)][TestCase(142u,6)] public void FloodedDocksPreserveDryStartsAndVisibleWater(uint seed,int players){var setup=new MatchSetup{theme=MapGen.DocksTheme,seed=seed,players=Enumerable.Range(0,players).Select(_=>new PlayerSetup{fighters=new[]{"ciantia"}}).ToArray()};var m=Match.New(setup);Assert.GreaterOrEqual(m.S.tiles.Count(t=>t.terrain==Terrain.Agua),m.S.width);Assert.IsTrue(m.S.fighters.All(f=>m.S.At(f.cell).terrain!=Terrain.Agua));}

 [TestCase("nikola","eletaser")][TestCase("bifia","flecha-lunar")][TestCase("desland","xeque-mate")] public void NewHeroesCanDestroyAnEmptyEnemyGearCellWithExactlyThreeAttacks(string hero,string skill){var m=New(hero,"nikola");var f=Hero(m);var n=Hero(m,2);var cell=f.cell+new Cell(1,0);var g=new Gear{owner=n.id,cell=Board.Index(m.S,cell),hits=3,value=1};m.S.Luna.gears.Add(g);int pm=f.pm;for(int i=0;i<3;i++){Assert.IsTrue(Skill(m,f,skill,cell,out var why),why);if(i<2)Assert.AreEqual(2-i,g.hits);}Assert.IsFalse(m.S.Luna.gears.Contains(g));Assert.AreEqual(pm,f.pm);}
 [Test] public void SphereBlastCountsOneGearHitRegardlessOfTwoDamage(){var m=New("nepturius","nikola");var f=Hero(m);var n=Hero(m,2);var sp=m.S.fighters.First(x=>x.def=="esfera-nepturius");sp.cell=new Cell(5,5);var g=new Gear{owner=n.id,cell=Board.Index(m.S,new Cell(6,5)),hits=3,value=1};m.S.Luna.gears.Add(g);Call(m,"SphereBlast",f,false);Assert.AreEqual(2,g.hits);}
 [Test] public void RandomAntimatterCubeCanHitGears(){var m=New("nepturius","nikola");var copy=JsonUtility.FromJson<MatchState>(JsonUtility.ToJson(m.S));var c=new Cell(Dice.Range(copy,copy.width),Dice.Range(copy,copy.height));var g=new Gear{owner=Hero(m,2).id,cell=Board.Index(m.S,c),hits=3,value=1};m.S.Luna.gears.Add(g);Call(m,"AntimatterCube",Hero(m));Assert.AreEqual(2,g.hits);}

 [Test] public void ChessDomainExposesAllFiveMovesAndRemovesThemAtEnd(){var m=New("desland");var f=Hero(m);Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);Assert.AreEqual(5,Match.Skills(f).Count(x=>x.effect!=null&&x.effect.StartsWith("mover-")));Call(m,"EndChess",f);Assert.AreEqual(0,Match.Skills(f).Count(x=>x.effect!=null&&x.effect.StartsWith("mover-")));}
 [Test] public void ChessDomainKnightMoveCanMoveAnAlliedCharacter(){var m=New("desland");var f=Hero(m);var ally=(Fighter)Call(m,"Spawn","ciantia",f.team,new Cell(1,1),f.id);Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);var target=new[]{new Cell(3,2),new Cell(2,3),new Cell(0,3),new Cell(3,0)}.First(c=>Board.At(m.S,c)==null&&Board.Walkable(m.S,c,false));Assert.IsTrue(Skill(m,f,"mover-cavalo",ally.cell,out why,target),why);Assert.AreEqual(target,ally.cell);}

 // Autor 23/10: na matriz não ataca, e a saída só vale a partir do próximo turno.
 [Test] public void MatrixBlocksAttacksAndSameTurnExit(){var m=New("nikola");var n=Hero(m);var e=Hero(m,2);n.cell=new Cell(4,4);e.cell=new Cell(6,4);n.pa=20;
  Assert.IsTrue(Skill(m,n,"matriz-protecao",n.cell,out var why),why);
  Assert.IsFalse(Skill(m,n,"eletaser",e.cell,out _),"não ataca dentro da matriz");
  var g=new Cell(9,9);m.S.Luna.gears.Add(new Gear{owner=n.id,cell=Board.Index(m.S,g),value=1,hits=3});
  Assert.IsFalse(Skill(m,n,"saida-matriz",g,out _),"não sai no mesmo turno");
  Call(m,"LunaEndTurn",n);n.pa=20;
  Assert.IsTrue(Skill(m,n,"saida-matriz",g,out why),why);}
 // Autor 23/10: depois da ultimate as peças somem (fluxo real de turnos, só passando).
 // Autor 24/10: as peças ficam depois da ult; ultar de novo só repõe as que caíram.
 [Test] public void ChessPiecesStayAfterTheDomainInRealTurns(){var m=New("desland");var f=Hero(m);Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);
  int deslandTurns=1;for(int k=0;k<40&&f.form=="dominio";k++){var a=m.S.Active;if(a==null)break;if(a==f&&k>0)deslandTurns++;Assert.IsTrue(m.Apply(new Command{kind="passar",fighter=a.id,revision=m.S.revision},a.team,out _,out why),why);}
  Assert.AreNotEqual("dominio",f.form);Assert.LessOrEqual(deslandTurns,4);Assert.IsTrue(m.S.fighters.Any(x=>x.Alive&&x.def.StartsWith("peca-")),"peças sumiram");}
 [Test] public void RecastOnlyRespawnsMissingPieces(){var m=New("desland");var f=Hero(m);f.pa=12;Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);Call(m,"EndChess",f);var torre=m.S.fighters.First(x=>x.Alive&&x.def=="peca-torre");torre.hp=0;torre.deathProcessed=true;int bispo=m.S.fighters.First(x=>x.Alive&&x.def=="peca-bispo").id;f.cooldowns.Clear();f.used.Clear();Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out why),why);var alive=m.S.fighters.Where(x=>x.Alive&&x.summoner==f.id&&x.def.StartsWith("peca-")).ToList();Assert.AreEqual(5,alive.Count);Assert.AreEqual(5,alive.Select(x=>x.def).Distinct().Count());Assert.IsTrue(alive.Any(x=>x.id==bispo),"o bispo vivo é o mesmo");}
 [Test] public void PieceOnlyMovesWithItsOwnMoveAndMovesChainInOneTurn(){var m=New("desland");var f=Hero(m);f.pa=12;Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);var torre=m.S.fighters.First(x=>x.Alive&&x.def=="peca-torre");Assert.IsFalse(Skill(m,f,"mover-bispo",torre.cell,out why,torre.cell+new Cell(1,1)));StringAssert.Contains("movimento dela",why);
  var a=(Fighter)Call(m,"Spawn","perry",f.team,new Cell(7,1),0);f.pa=12;Assert.IsTrue(Skill(m,f,"mover-peao",a.cell,out why,new Cell(7,2)),why);Assert.IsTrue(Skill(m,f,"mover-cavalo",new Cell(7,2),out why,new Cell(8,4)),why);Assert.IsTrue(Skill(m,f,"mover-torre",new Cell(8,4),out why,new Cell(8,7)),why);Assert.IsTrue(Skill(m,f,"mover-bispo",new Cell(8,7),out why,new Cell(10,9)),why);Assert.AreEqual(new Cell(10,9),a.cell);}

