 static List<GameEvent> Ev(Match m)=>(List<GameEvent>)typeof(Match).GetField("events",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(m);
 static Fighter Sph(Match m,Fighter owner)=>m.S.fighters.First(x=>x.def=="esfera-nepturius"&&x.summoner==owner.id);
 [Test] public void SphereStepsCostOneEvenOnWater(){var m=New("nepturius");var sp=Sph(m,Hero(m));var to=sp.cell+new Cell(1,0);m.S.At(to).terrain=Terrain.Agua;m.S.At(to).height=2;Assert.AreEqual(1,Board.Step(m.S,sp,sp.cell,to,false));}
 [Test] public void BlastSparesOwnerAndHitsNoHarderWhileOwnerLives(){var m=New("nepturius");var n=Hero(m);var e=Hero(m,2);var sp=Sph(m,n);sp.cell=new Cell(6,6);n.cell=new Cell(6,7);e.cell=new Cell(7,6);e.hp=20;int own=n.hp;Call(m,"SphereBlast",n,false);Assert.AreEqual(own,n.hp);Assert.AreEqual(18,e.hp);}
 [Test] public void BlastHitsTwoHarderAfterOwnerDies(){var m=New("nepturius");var n=Hero(m);var e=Hero(m,2);var sp=Sph(m,n);sp.cell=new Cell(6,6);e.cell=new Cell(7,6);e.hp=20;n.hp=0;Call(m,"KO",n,null);Call(m,"SphereBlast",n,true);Assert.AreEqual(16,e.hp);}
 [Test] public void SphereCanStillMoveAfterBlackMadness(){var m=New("nepturius");var n=Hero(m);var sp=Sph(m,n);n.pa=6;sp.cell=n.cell+new Cell(1,0);Call(m,"LunaBeginTurn",n);Assert.AreEqual(6,n.pa);Assert.IsTrue(Skill(m,n,"loucura-negra",n.cell,out var why),why);Assert.IsTrue(Skill(m,n,"mover-esfera",sp.cell+new Cell(3,0),out why),why);}
 [Test] public void BlackMadnessAfterMovingSphereAddsFourPm(){var m=New("nepturius");var n=Hero(m);var sp=Sph(m,n);n.pa=6;n.cell=new Cell(2,2);sp.cell=new Cell(6,6);Call(m,"LunaBeginTurn",n);int pm0=sp.pm;Assert.IsTrue(Skill(m,n,"mover-esfera",sp.cell+new Cell(1,0),out var why),why);Assert.AreEqual(pm0-1,sp.pm);Assert.IsTrue(Skill(m,n,"loucura-negra",n.cell,out why),why);Assert.AreEqual(pm0+3,sp.pm);Assert.IsTrue(Skill(m,n,"mover-esfera",new Cell(6,6),out why),why);}
 [Test] public void EchoCloneLastsTwoOfItsOwnTurns(){var m=New("desland","nikola");var d=Hero(m);var clone=(Fighter)Call(m,"CreateClone",d,Hero(m,2));Assert.NotNull(clone);Call(m,"LunaEndTurn",d);Assert.IsTrue(clone.Alive,"o fim do turno do Desland não gasta o eco");Call(m,"LunaEndTurn",clone);Assert.IsTrue(clone.Alive,"1º turno do eco");Call(m,"LunaEndTurn",d);Call(m,"LunaEndTurn",clone);Assert.IsFalse(clone.Alive,"some depois do 2º turno");}
