 [Test] public void GearIntervalFollowsPlayerCount(){var m=New("nikola");Assert.AreEqual(4,m.GearEvery());m.S.players=4;Assert.AreEqual(3,m.GearEvery(),"dupla x dupla = x3");Call(m,"Spawn","perry",3,new Cell(9,9),0);m.S.players=3;Assert.AreEqual(3,m.GearEvery());Call(m,"Spawn","perry",4,new Cell(9,10),0);m.S.players=4;Assert.AreEqual(2,m.GearEvery());Call(m,"Spawn","perry",5,new Cell(9,11),0);m.S.players=5;Assert.AreEqual(1,m.GearEvery());}
 [Test] public void BotsNeverTargetTheSphere(){var m=New("ciantia","nepturius");var foes=(List<Fighter>)typeof(Bot).GetMethod("Foes",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{m.S,Hero(m)});Assert.IsFalse(foes.Any(x=>x.def=="esfera-nepturius"));Assert.IsTrue(foes.Any(x=>x.def=="nepturius"));}
 [Test] public void MadSphereActsAtTheEndOfEveryTurn(){var m=New("nepturius");var n=Hero(m);var e=Hero(m,2);n.hp=0;Call(m,"KO",n,null);int before=Ev(m).Count;Call(m,"LunaEndTurn",e);Assert.IsTrue(Ev(m).Skip(before).Any(x=>x.info=="explosao-antimateria"||x.info=="agarrao-negro"));}
