 [Test] public void DeslandMovesAllyAndEnemyWithChessDuringDomain(){var m=New("desland");var f=Hero(m);f.cell=new Cell(2,2);var a=(Fighter)Call(m,"Spawn","perry",f.team,new Cell(8,8),0);var e=Hero(m,2);e.cell=new Cell(9,4);f.pa=12;Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);Assert.AreEqual("dominio",f.form);Assert.AreEqual(1,Content.Form(f).armor);Assert.IsTrue(m.CanTarget(f,Content.Skill(f,"mover-torre"),a.cell,out why),why);Assert.IsTrue(Skill(m,f,"mover-torre",a.cell,out why,a.cell+new Cell(0,3)),why);Assert.AreEqual(new Cell(8,11),a.cell);Assert.IsTrue(Skill(m,f,"mover-rainha",e.cell,out why,e.cell+new Cell(2,2)),why);Assert.AreEqual(new Cell(11,6),e.cell);Assert.IsTrue(Match.Skills(f).Any(x=>x.id=="mover-rainha"));}
 // Peças do xadrez (autor 24/10).
 static Fighter Piece(Match m,Fighter f,string def)=>m.S.fighters.First(x=>x.Alive&&x.def==def&&x.summoner==f.id);
 static Match Board3(out Fighter f,out Fighter e){var m=New("desland");f=Hero(m);e=Hero(m,2);f.pa=12;Assert.IsTrue(Skill(m,f,"dominio-xadrez",f.cell,out var why),why);foreach(var p in m.S.fighters.Where(x=>x.def.StartsWith("peca-")))p.cell=new Cell(0,11-p.id%5);f.cell=new Cell(11,0);return m;}
 [Test] public void BishopHitsUpToThreeCellsOnItsDiagonal(){var m=Board3(out var f,out var e);var b=Piece(m,f,"peca-bispo");b.cell=new Cell(5,5);e.cell=new Cell(8,8);e.hp=20;m.S.At(new Cell(6,6)).terrain=Terrain.Caixa;Assert.IsTrue((bool)Call(m,"ChessCapture",b,f));Assert.Less(e.hp,20);e.cell=new Cell(9,9);Assert.IsNull(Call(m,"PieceHunt",b,f));}
 [Test] public void TowerHasThreeHpStunsAndArmorsNeighbours(){var m=Board3(out var f,out var e);var t=Piece(m,f,"peca-torre");Assert.AreEqual(3,Content.MaxHp(t));t.cell=new Cell(5,5);var ally=(Fighter)Call(m,"Spawn","perry",f.team,new Cell(5,6),0);Assert.AreEqual(1,(int)Call(m,"TowerArmor",ally));e.cell=new Cell(6,5);e.hp=20;Assert.IsTrue((bool)Call(m,"ChessCapture",t,f));Assert.AreEqual(1,e.stunned);}
 [Test] public void KnightHitsEveryFoeNextToWhereItLands(){var m=Board3(out var f,out var e);var k=Piece(m,f,"peca-cavalo");k.cell=new Cell(4,4);e.cell=new Cell(6,6);e.hp=20;Call(m,"ChessAdvance",k,f,null);Assert.AreEqual(1,Board.Gap(k,e));Assert.Less(e.hp,20);}
 [Test] public void PiecesIgnoreTerrainAndConditions(){var m=Board3(out var f,out var e);var q=Piece(m,f,"peca-rainha");q.cell=new Cell(2,2);for(int x=3;x<6;x++){m.S.At(new Cell(x,2)).terrain=Terrain.Agua;m.S.At(new Cell(x,2)).height=3;}m.S.At(new Cell(4,2)).terrain=Terrain.Caixa;Assert.IsTrue((bool)typeof(Match).GetMethod("ChessMove",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(m,new object[]{q.cell,new Cell(6,2),"mover-rainha",q}));Assert.IsTrue(m.S.fighters.Where(x=>x.def.StartsWith("peca-")).All(x=>Content.Def(x).luna.techProtect));}
