 [Test] public void EzequielaMatchesAuthorSpecOf2410(){var d=Content.Default("ezequiela");Assert.AreEqual(2,d.illusionCount);SkillDef S(string id)=>d.skills.First(x=>x.id==id);var e=S("espelho-primordial");Assert.AreEqual(2,e.invertTurns);Assert.AreEqual(2,e.cooldown);var c=S("ilusao-confusa");Assert.AreEqual(2,c.pmLoss);Assert.AreEqual(3,c.pa);Assert.AreEqual(2,S("copia-ezequiela").maxActive);var f=S("medo-ezequiela");Assert.AreEqual(2,f.maxRange);Assert.AreEqual(2,f.pa);Assert.AreEqual(4,f.push);Assert.AreEqual(0,f.damage);Assert.AreEqual(1,f.perMatch);var p=S("portal-ezequiela");Assert.AreEqual(6,p.maxRange);Assert.AreEqual(2,p.pa);Assert.IsFalse(p.sight);Assert.AreEqual(2,p.minRound);Assert.IsTrue(p.ultimate);
  var m=Match.New(new MatchSetup{flatMap=true,seed=3,players=new[]{new PlayerSetup{fighters=new[]{"ezequiela"}},new PlayerSetup{fighters=new[]{"ciantia"}}}});var z=m.S.fighters.First(x=>x.def=="ezequiela");var ils=m.S.fighters.Where(x=>x.def=="ilusao").ToList();Assert.AreEqual(2,ils.Count);foreach(var x in ils){Assert.AreEqual(1,x.hp,"PV da cópia");Assert.AreEqual(Content.MaxPm(z,m.S),Content.MaxPm(x,m.S),"PM da cópia");}Assert.IsTrue(d.skills.First(x=>x.id=="espelho-primordial").CanHitAlly&&d.skills.First(x=>x.id=="espelho-primordial").CanHitEnemy,"espelho em aliados e inimigos");var free=Enumerable.Range(-2,5).SelectMany(dx=>Enumerable.Range(-2,5).Select(dz=>z.cell+new Cell(dx,dz))).First(c=>Board.Contains(m.S,c)&&Board.At(m.S,c)==null&&Board.Gap(z,c)>=1&&Board.Gap(z,c)<=2&&m.S.At(c).terrain==Terrain.Livre);m.S.active=m.S.timeline.IndexOf(z.id);z.pa=6;Assert.IsFalse(m.CanTarget(z,Content.Skill(z,"copia-ezequiela"),free,out var why));StringAssert.Contains("Limite",why,"no máximo 2 cópias no mapa");}
 // Viúva da Agulha e ajustes de 24/10 (noite).
 static Match Widow(out Fighter w,out Fighter e){var m=New("viuva-da-agulha");w=Hero(m);e=Hero(m,2);w.cell=new Cell(2,2);e.cell=new Cell(9,9);return m;}
 [Test] public void WebCoversFourByFourAndHidesTheFamily(){var m=Widow(out var w,out var e);Assert.IsTrue(Skill(m,w,"viuva-da-agulha-teia",new Cell(3,2),out var why),why);Assert.AreEqual(16,m.S.Luna.webs.Single().cells.Length);var sp=(Fighter)Call(m,"Spawn","aranha-viuva",w.team,new Cell(4,3),w.id);Call(m,"WebTouch",sp,sp.cell,null);Assert.IsTrue(sp.hidden);Call(m,"WebTouch",e,new Cell(3,3),null);Assert.AreEqual(e.id,m.S.Luna.webs[0].last);Assert.IsFalse(e.hidden);}
 [Test] public void WidowHasNoHideAndShowsUpOffTheWeb(){var m=Widow(out var w,out var e);Assert.IsFalse(Content.Def(w).skills.Any(s=>s.kind==SkillKind.Esconder));Assert.IsTrue(Skill(m,w,"viuva-da-agulha-teia",new Cell(3,2),out var why),why);Assert.IsTrue(w.hidden,"em cima da teia some");Call(m,"WebTouch",w,new Cell(8,8),null);Assert.IsFalse(w.hidden,"fora da teia aparece");}
 [Test] public void WebLastsThreeOfTheWidowsTurns(){var m=Widow(out var w,out var e);Assert.IsTrue(Skill(m,w,"viuva-da-agulha-teia",new Cell(3,2),out var why),why);Assert.IsTrue(w.hidden);Call(m,"LunaBeginTurn",w);Call(m,"LunaBeginTurn",w);Assert.AreEqual(16,m.S.Luna.webs.Single().cells.Length,"turnos 2 e 3 ainda com teia");Assert.IsTrue(w.hidden);Call(m,"LunaBeginTurn",w);Assert.AreEqual(0,m.S.Luna.webs.Single().cells.Length,"some no 4º turno");Assert.IsFalse(w.hidden,"sem teia, aparece");}
 [Test] public void UpToThreeSpidersAndTheyHuntTheWebIntruder(){var m=Widow(out var w,out var e);Assert.AreEqual(3,Content.Default("viuva-da-agulha").skills.First(x=>x.id=="viuva-da-agulha-clone-das-sombras").maxActive);Assert.AreEqual("aranha-viuva",Content.Default("viuva-da-agulha").skills.First(x=>x.id=="viuva-da-agulha-clone-das-sombras").summon);
  Assert.IsTrue(Skill(m,w,"viuva-da-agulha-teia",new Cell(4,4),out var why),why);e.cell=new Cell(4,4);e.hp=20;Call(m,"WebTouch",e,e.cell,null);var sp=(Fighter)Call(m,"Spawn","aranha-viuva",w.team,new Cell(4,0),w.id);Call(m,"SpidersAct",w);Assert.AreEqual(1,Board.Gap(sp,e),"andou até o intruso");Assert.AreEqual(19,e.hp,"mordida de 1 sem errar na teia");}
 [Test] public void WithoutIntruderSpidersFollowMotherAndBiteHerTarget(){var m=Widow(out var w,out var e);var sp=(Fighter)Call(m,"Spawn","aranha-viuva",w.team,new Cell(2,6),w.id);e.cell=new Cell(2,8);Call(m,"WebPrey",w,e);Call(m,"SpidersAct",w);Assert.AreEqual(1,Board.Gap(sp,e));var bite=Content.AnySkill("mordida-aranha");Assert.IsNull(bite,"mordida é interna");}
 [Test] public void WebSticksFoesForFourPmOncePerTurn(){var m=Widow(out var w,out var e);Assert.IsTrue(Skill(m,w,"viuva-da-agulha-teia",new Cell(4,4),out var why),why);e.used.Clear();e.pm=6;Call(m,"WebTouch",e,new Cell(4,4),null);Assert.AreEqual(2,e.pm);Call(m,"WebTouch",e,new Cell(5,4),null);Assert.AreEqual(2,e.pm,"uma vez por turno");w.used.Clear();Call(m,"WebTouch",w,new Cell(4,4),null);Assert.IsFalse(w.used.Contains("teia-grudou"),"a Viúva não gruda");}
